import{_ as a,a as r,c as t,ac as i}from"./chunks/framework.BSuaGltH.js";const u=JSON.parse('{"title":"安全加固：变更、排障与恢复自检","description":"先交代变更和恢复条件，再按故障证据检验机制。","frontmatter":{"title":"安全加固：变更、排障与恢复自检","description":"先交代变更和恢复条件，再按故障证据检验机制。","showdocs":{"topics":[{"id":"hardening","title":"安全配置","link":"/topics/hardening/"}],"kind":"知识专题","scope":"general","audience":"general","group":"容器与运维","seriesTitle":"安全加固：最小权限与可回退基线","summary":"先交代变更和恢复条件，再按故障证据检验机制。","status":"active","related":[{"title":"安全加固：配置最小权限服务与访问限制","link":"/systems/security-access/hardening/plus/practice/application","kind":"应用实践","scope":"general","audience":"general"},{"title":"安全加固：对象、配置与机制","link":"/systems/security-access/hardening/baseline","kind":"知识专题","scope":"general","audience":"general"}],"prev":{"text":"安全加固：配置最小权限服务与访问限制","link":"/systems/security-access/hardening/plus/practice/application"},"next":false},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"安全加固：配置最小权限服务与访问限制","link":"/systems/security-access/hardening/plus/practice/application"},"next":false},"headers":[],"relativePath":"systems/security-access/hardening/operations.md","filePath":"systems/security-access/hardening/operations.md"}'),s={name:"systems/security-access/hardening/operations.md"};function n(c,e,o,p,l,d){return r(),t("div",null,[...e[0]||(e[0]=[i('<h1 id="安全加固-变更、排障与恢复自检" tabindex="-1">安全加固：变更、排障与恢复自检 <a class="header-anchor" href="#安全加固-变更、排障与恢复自检" aria-label="Permalink to &quot;安全加固：变更、排障与恢复自检&quot;">​</a></h1><h2 id="part-1" tabindex="-1">补丁、审计与基线变更 <a class="header-anchor" href="#part-1" aria-label="Permalink to &quot;补丁、审计与基线变更 {#part-1}&quot;">​</a></h2><p>维护systemd 最小权限任务前先保存执行用户、只读程序目录与必要写入路径，恢复后以加载后的 unit、实际进程权限与拒绝日志验收。具体配置见<a href="/systems/security-access/hardening/plus/practice/application#product-config">配套示例</a>。</p><h3 id="part-1-secrets" tabindex="-1">秘密与备份保护 <a class="header-anchor" href="#part-1-secrets" aria-label="Permalink to &quot;秘密与备份保护 {#part-1-secrets}&quot;">​</a></h3><p>秘密管理覆盖配置、环境、日志、崩溃转储和备份。限制读取、按用途分发、定期轮换，不能仅从仓库删除字符串就认为泄露已解决。备份含同样敏感数据，必须有访问限制和恢复演练计划。</p><h3 id="part-1-drift" tabindex="-1">基线漂移与例外 <a class="header-anchor" href="#part-1-drift" aria-label="Permalink to &quot;基线漂移与例外 {#part-1-drift}&quot;">​</a></h3><p>基线漂移应区分批准例外与意外偏离。每个例外记录原因、负责人、补偿控制和到期日期；到期后复审，不自动无限延长。观察到参数不同先确认实际服务配置与平台支持，再决定修复，不能把文本差异直接当漏洞。</p><h3 id="part-1-exercise" tabindex="-1">练习与参考解答 <a class="header-anchor" href="#part-1-exercise" aria-label="Permalink to &quot;练习与参考解答 {#part-1-exercise}&quot;">​</a></h3><p>练习：配置仓库曾提交令牌，删除当前文件中的令牌就能关闭事件吗？某临时例外已过期，能否因业务繁忙自动永久保留？</p><details class="details custom-block"><summary>参考解答</summary><p>不能，历史副本、日志和备份可能仍含令牌，应撤销/轮换并核查使用范围，限制敏感副本读取。例外需负责人、补偿控制和到期复审，不自动延长；先确认实际漂移和平台支持，再按批准的恢复/更新计划处理，不能把文本差异直接等同运行漏洞。</p></details><h2 id="part-2" tabindex="-1">加固后启动失败与权限排障 <a class="header-anchor" href="#part-2" aria-label="Permalink to &quot;加固后启动失败与权限排障 {#part-2}&quot;">​</a></h2><p>本节沿加载后的 unit、实际进程权限与拒绝日志定位失败层；先确认执行用户、只读程序目录与必要写入路径，与<a href="/systems/security-access/hardening/plus/practice/application#product-config">配套示例</a>逐项对照，再选择最小修复。</p><h3 id="part-2-broken" tabindex="-1">收紧后服务失效 <a class="header-anchor" href="#part-2-broken" aria-label="Permalink to &quot;收紧后服务失效 {#part-2-broken}&quot;">​</a></h3><p>服务失效先关联最近加固变更、拒绝日志和失败资源；仅对必要路径或能力最小放宽，保存证据后再调整正式基线。不要全局关闭SELinux、撤销所有ACL或改成root运行。若影响管理通道，按预定旁路恢复上一份已批准配置。</p><h3 id="part-2-evidence" tabindex="-1">声明与实际生效 <a class="header-anchor" href="#part-2-evidence" aria-label="Permalink to &quot;声明与实际生效 {#part-2-evidence}&quot;">​</a></h3><p>生效证据需要区分配置文件声明、管理器加载、进程实际权限与访问行为四层，后两层属于运行状态证据。本课只能静态审阅第一层与离线输入，不能声称沙箱或ACL已经在机器上生效。读者另行验收时要记录平台、服务版本和正反行为结果，不能以配置存在替代安全保证。</p><h3 id="part-2-exercise" tabindex="-1">练习与参考解答 <a class="header-anchor" href="#part-2-exercise" aria-label="Permalink to &quot;练习与参考解答 {#part-2-exercise}&quot;">​</a></h3><p>练习：unit文本已含NoNewPrivileges和只读根，离线case.json也判为一致，但并未加载unit。能否记录“沙箱已生效”？如果收紧后报告只读文件系统错误，应如何最小恢复？</p><details class="details custom-block"><summary>参考解答</summary><p>不能，目前只有声明与人工输入，缺管理器加载、进程权限及访问行为证据。后续另行获准运行时需核对加载配置与正反访问结果；只读错误先定位实际失败路径和最近变更，仅放行确有必要的状态目录并保存证据，不全局关闭隔离或改用root掩盖问题。</p></details><h2 id="part-3" tabindex="-1">收紧权限后服务异常的复盘 <a class="header-anchor" href="#part-3" aria-label="Permalink to &quot;收紧权限后服务异常的复盘 {#part-3}&quot;">​</a></h2><p>以下演练将systemd 最小权限任务的变更、失败证据和恢复验收串起来；先熟悉<a href="/systems/security-access/hardening/plus/practice/application#product-config">配套示例</a>中的执行用户、只读程序目录与必要写入路径。演练未执行。</p><h3 id="part-3-incident-scenario" tabindex="-1">故障场景与影响 <a class="header-anchor" href="#part-3-incident-scenario" aria-label="Permalink to &quot;故障场景与影响 {#part-3-incident-scenario}&quot;">​</a></h3><p>应用加固后无法写日志，运维准备取消全部沙箱限制。</p><p>先记录首次异常时间、受影响对象和最近变更，区分个别对象失败与整条管理链路异常。以下是排查演练，不是已发生事故的实测记录。</p><h3 id="part-3-incident-evidence" tabindex="-1">按证据定位原因 <a class="header-anchor" href="#part-3-incident-evidence" aria-label="Permalink to &quot;按证据定位原因 {#part-3-incident-evidence}&quot;">​</a></h3><ol><li>确认失败写入的实际路径、服务身份和错误来源，区分路径权限与服务文件系统视图限制。</li><li>比较变更前后 unit、已加载设置和进程状态；配置里有某个选项不等于限制已经生效。</li><li>列出业务必需的状态、缓存与日志目录，检查是否误依赖程序目录或共享根路径写入。</li></ol><h3 id="part-3-incident-recovery" tabindex="-1">恢复步骤与验收 <a class="header-anchor" href="#part-3-incident-recovery" aria-label="Permalink to &quot;恢复步骤与验收 {#part-3-incident-recovery}&quot;">​</a></h3><p>优先将写入迁入专用状态或日志目录，仅增加必要路径例外；若确需撤回，单独撤销已证实不兼容的项，保留其余限制。</p><p>验收：必要读写与连接成功，不必要路径写入和越权操作仍被拒绝；再次检查进程身份与实际限制，记录例外的用途和负责人。</p><p>将触发条件、直接原因、修复动作、恢复证据和后续检查写入同一份复盘，明确每项后续工作的负责人。机制参考：<a href="https://docs.kernel.org/userspace-api/no_new_privs.html" target="_blank" rel="noopener noreferrer">官方说明</a>。</p><h3 id="part-3-check" tabindex="-1">机制自检 <a class="header-anchor" href="#part-3-check" aria-label="Permalink to &quot;机制自检 {#part-3-check}&quot;">​</a></h3><p>自检：根据上面的场景画出故障链，标出每一项证据来自哪个对象、发生在哪个时间。说明恢复动作改变了什么，以及为什么其他原本允许或拒绝的操作仍符合预期。</p><h3 id="part-3-answers" tabindex="-1">参考解答与误区 <a class="header-anchor" href="#part-3-answers" aria-label="Permalink to &quot;参考解答与误区 {#part-3-answers}&quot;">​</a></h3><p>问题一：NoNewPrivileges会撤销已持有的root权限吗？</p><p>答案：不会。它约束后续exec获得新增权限并由后代继承，还需专用账户与能力集合来限制已有权限。</p><p>问题二：ProtectSystem=strict后程序需要写日志，是否加入根目录写例外？</p><p>答案：不应。先判断是否能写journal或明确专用状态目录，只为必要路径设置最小例外。只读挂载视图不等于宿主机磁盘被永久改写。</p><p>问题三：配置文件含沙箱选项能否说明已生效？</p><p>答案：不能。还需确认管理器加载、内核支持、进程实际状态和正反访问行为。</p><h3 id="part-3-acceptance" tabindex="-1">验收与未验证项 <a class="header-anchor" href="#part-3-acceptance" aria-label="Permalink to &quot;验收与未验证项 {#part-3-acceptance}&quot;">​</a></h3><p>验收应覆盖正常操作、预期拒绝和恢复后的再次操作，并记录实际版本、身份、配置及结果。本文示例未执行；配置审阅与离线推演不能替代真实环境的连通、权限和恢复验证。</p><h3 id="part-3-sources" tabindex="-1">版本、来源与进一步阅读 <a class="header-anchor" href="#part-3-sources" aria-label="Permalink to &quot;版本、来源与进一步阅读 {#part-3-sources}&quot;">​</a></h3><p>核对日期：2026-10-17。教学版本族：systemd256固定文档、Linux no_new_privs与Windows ACL概念。固定源码用于重现字段，动态官方网页用于补充说明，不称为2026最新版本。具体字段与语义以本节所列一手资料及目标版本手册为准。</p><ul><li><a href="https://github.com/systemd/systemd/blob/v256/man/systemd.exec.xml" target="_blank" rel="noopener noreferrer">systemd256执行环境固定源码</a></li><li><a href="https://learn.microsoft.com/en-us/windows/security/identity-protection/access-control/access-control" target="_blank" rel="noopener noreferrer">Windows访问控制</a></li><li><a href="https://docs.kernel.org/userspace-api/no_new_privs.html" target="_blank" rel="noopener noreferrer">Linux内核no_new_privs</a></li></ul>',44)])])}const m=a(s,[["render",n]]);export{u as __pageData,m as default};
